import{_ as o,a8 as a,o as l,c as n,ah as h,K as e}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const m=JSON.parse('{"title":"GitHub 直连 clone 被重置时用 codeload zip 兜底","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["工具","GitHub","网络","踩坑"]},"headers":[],"relativePath":"vault/Memory/Lessons/GitHub克隆被重置的zip兜底.md","filePath":"vault/Memory/Lessons/GitHub克隆被重置的zip兜底.md","lastUpdated":1789374053000}'),r={name:"vault/Memory/Lessons/GitHub克隆被重置的zip兜底.md"};function p(d,i,c,k,g,b){const s=a("NolebaseGitContributors"),t=a("NolebaseGitChangelog");return l(),n("div",null,[i[0]||(i[0]=h(`<h1 id="github-直连-clone-被重置时用-codeload-zip-兜底" tabindex="-1">GitHub 直连 clone 被重置时用 codeload zip 兜底 <a class="header-anchor" href="#github-直连-clone-被重置时用-codeload-zip-兜底" aria-label="Permalink to “GitHub 直连 clone 被重置时用 codeload zip 兜底”">​</a></h1><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to “现象”">​</a></h2><p>本机（Windows）<code>git clone https://github.com/...</code> 报 <code>Recv failure: Connection was reset</code>；但 <code>api.github.com</code> 与 <code>codeload.github.com</code> 可达，Google Fonts CDN 也可达。 网络对 github.com 主站与 git 协议不稳定，部分域与 CDN 正常。</p><h2 id="解法" tabindex="-1">解法 <a class="header-anchor" href="#解法" aria-label="Permalink to “解法”">​</a></h2><p>用 codeload 下载 zip 再解压，代替 clone：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> --max-time</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> 120</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> repo.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#56B6C2;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">  &quot;https://codeload.github.com/&lt;owner&gt;/&lt;repo&gt;/zip/refs/heads/&lt;branch&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> repo.zip</span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # 解出 &lt;repo&gt;-&lt;branch&gt;/ 目录</span></span></code></pre></div><h2 id="附属经验" tabindex="-1">附属经验 <a class="header-anchor" href="#附属经验" aria-label="Permalink to “附属经验”">​</a></h2><ul><li>调研 GitHub 仓库信息优先走 <code>api.github.com/repos/&lt;owner&gt;/&lt;repo&gt;</code> （星数/默认分支/许可证/最近推送均可取）+ raw.githubusercontent.com 读文件</li><li><code>npx playwright install chromium</code> 下载（cdn.playwright.dev）正常，约 195MB</li><li>需要完整 git 历史时 zip 不行，可重试 clone 或换镜像，本项目场景 zip 足够</li></ul>`,8)),e(s),e(t)])}const C=o(r,[["render",p]]);export{m as __pageData,C as default};
